const title=$('Config').first().json.saleSheetName;
const sheets=$input.first().json.sheets||[];
const found=sheets.find(s=>String((s.properties||{}).title||'')===title);
return [{json:{needsCreate:!found,sheetId:found ? found.properties.sheetId : null}}];

const values=$input.first().json.values||[];
if(values.length<2) return [];
const headers=values[0].map(v=>String(v??'').trim());
const max=Math.max(1,Math.min(50,Number($('Config').first().json.maxAuditItems||20)));
function obj(row){const o={};headers.forEach((h,i)=>o[h]=row[i]??'');return o;}
function t(v){return v===null||v===undefined?'':String(v).trim();}
function n(v){const x=Number(v);return Number.isFinite(x)?x:null;}
const out=[];
for(let i=1;i<values.length;i++){
  const r=obj(values[i]);
  const itemId=t(r['Item ID']);
  const qty=n(r['Available Qty']);
  const price=n(r.Price);
  if(!itemId || qty===null || qty<=0 || price===null || price<=0) continue;
  out.push({json:{
    itemId,
    sku:t(r.SKU),
    title:t(r.Title),
    ebayUrl:t(r['eBay URL'])||('https://www.ebay.com/itm/'+itemId),
    currentPrice:price
  }});
  if(out.length>=max) break;
}
return out;

const COL={title:0,price:1,median:2,offer:3,net:4,margin:5,decision:6,status:7,itemId:8,sku:9,floor:10,sale:11};
function t(v){return v===null||v===undefined?'':String(v).trim();}
function num(v){if(v===null||v===undefined||v==='')return null;const x=Number(v);return Number.isFinite(x)?x:null;}
function normDecision(v){const s=t(v).toUpperCase();if(['ԱՅՈ','YES','Y','APPROVE'].includes(s))return 'YES';if(['ՈՉ','NO','N','SKIP'].includes(s))return 'NO';return '';}
function isDone(s){return t(s).startsWith('✅');}
const cfg=$('Config').first().json;
const selected=$('Select Active Listings').all();
const responses=$input.all();
const WIDTH=12;
const oldValues=$('Read Existing Sale Agent').first().json.values||[];
const knownLayout=t((oldValues[0]||[])[COL.itemId])==='Item ID';
function money(v){return Math.round((Number(v||0)+Number.EPSILON)*100)/100;}
function ceilMoney(v){return Math.ceil(v*100-1e-9)/100;}
function pad(row){const r=row.slice(0,WIDTH);while(r.length<WIDTH)r.push('');return r;}
const ST_RECHECK='⚠️ Գինը իջել է հաստատումից հետո — նորից հաստատիր';
const ST_STALE='⏸ Այլևս չի առաջարկվում';

// Economics: eBay fees apply to item + shipping charged to buyer
const feeRate=Number(cfg.ebayFeeRate??0.1325);
const perOrder=Number(cfg.ebayPerOrderFee??0.40);
const cost=Number(cfg.productCost??3);
const label=Number(cfg.shippingLabelCost??0);
const minMargin=Number(cfg.minMarginPct??25)/100;
const minNet=Number(cfg.minNetProfit??1);
const durationDays=Number(cfg.saleDurationDays??7);
function econ(sale,ship){const gross=sale+ship;const net=gross-gross*feeRate-perOrder-cost-label;return {net:money(net),margin:gross>0?net/gross:0};}
function floorPrice(ship){
  const fixed=perOrder+cost+label;
  const byMargin=(1-feeRate-minMargin)>0?fixed/(1-feeRate-minMargin)-ship:Infinity;
  const byProfit=(minNet+fixed)/(1-feeRate)-ship;
  return ceilMoney(Math.max(0.99,byMargin,byProfit));
}
// A DONE row stays (blocking a new suggestion) only while its sale is still running
function doneActive(status){
  const m=t(status).match(/(\d{4}-\d{2}-\d{2})/);
  if(!m) return true;
  return (Date.now()-new Date(m[1]+'T00:00:00Z').getTime())/86400000 < durationDays;
}

const oldMap={};
if(knownLayout){
  for(let i=1;i<oldValues.length;i++){
    const r=oldValues[i]||[];
    const itemId=t(r[COL.itemId]);
    if(!itemId) continue;
    oldMap[itemId]={decision:normDecision(r[COL.decision]),status:t(r[COL.status]),sale:num(r[COL.sale]),row:pad(r)};
  }
}

const rows=[];
const seen=new Set();
const generatedAt=new Date().toISOString();
let audited=0,insufficient=0,notAboveMarket=0,marginBlocked=0,recheck=0,stale=0,activeSales=0;
for(let i=0;i<selected.length;i++){
  const src=selected[i].json;
  const old=oldMap[src.itemId];
  if(old && isDone(old.status) && doneActive(old.status)){ rows.push(old.row); seen.add(src.itemId); activeSales++; continue; }
  const body=(responses[i]&&responses[i].json)||{};
  if(!body.ok || !body.audit){insufficient++;continue;}
  audited++;
  const audit=body.audit;
  const data=audit.data||audit.DATA||{};
  const market=audit.market||audit.MARKET||{};
  const exact=Number(market.exactCompetitorCount||0);
  const median=num(market.medianComparableBuyerTotal);
  const ownTotal=num(market.ourBuyerTotal);
  let shipping=num(data.shipping);
  if(shipping===null && ownTotal!==null) shipping=money(Math.max(0,ownTotal-src.currentPrice));
  shipping=shipping||0;
  if(exact<2 || median===null || median<=0){insufficient++;continue;}
  const targetItem=money(Math.max(0.99,median-shipping));
  if(src.currentPrice<=targetItem*1.03){notAboveMarket++;continue;}
  const needed=((src.currentPrice-targetItem)/src.currentPrice)*100;
  let discount=Math.max(5,Math.min(15,Math.round(needed/5)*5));
  const floor=floorPrice(shipping);
  while(discount>=5 && money(src.currentPrice*(1-discount/100))<floor) discount-=5;
  if(discount<5){marginBlocked++;continue;}
  const salePrice=money(src.currentPrice*(1-discount/100));
  const e=econ(salePrice,shipping);

  let decision=old?old.decision:'';
  let status=old&&t(old.status).startsWith('❌')?old.status:'';
  if(decision==='YES' && (old.sale===null || salePrice<old.sale-0.001)){
    decision='';status=ST_RECHECK;recheck++;
  }
  const title=(src.title||src.sku||src.itemId);
  const shortTitle=(title.length>80?title.slice(0,77)+'...':title).replace(/"/g,'""');
  const safeUrl=String(src.ebayUrl||('https://www.ebay.com/itm/'+src.itemId)).replace(/"/g,'');
  seen.add(src.itemId);
  rows.push([
    '=HYPERLINK("'+safeUrl+'","'+shortTitle+'")',
    src.currentPrice,
    median,
    '−'+discount+'% → $'+salePrice.toFixed(2),
    e.net,
    Math.round(e.margin*1000)/10,
    decision==='YES'?'ԱՅՈ':decision==='NO'?'ՈՉ':'',
    status,
    src.itemId,
    src.sku,
    floor,
    salePrice
  ]);
}

// Keep running sales and surface approvals that were not re-suggested, so nothing disappears silently
for(const itemId of Object.keys(oldMap)){
  if(seen.has(itemId)) continue;
  const old=oldMap[itemId];
  if(isDone(old.status) && doneActive(old.status)){ rows.push(old.row); activeSales++; continue; }
  if(old.decision==='YES' && !isDone(old.status)){
    const row=old.row.slice();
    row[COL.decision]='';
    row[COL.status]=ST_STALE;
    rows.push(row); stale++;
  }
}
return [{json:{rows,rowCount:rows.length,audited,insufficient,notAboveMarket,marginBlocked,recheck,stale,activeSales,generatedAt}}];

const s=$('Build Simple Sale Rows').first().json;
return [{json:{
  ok:true,
  rowsInSheet:s.rowCount,
  audited:s.audited,
  insufficient:s.insufficient,
  notAboveMarket:s.notAboveMarket,
  marginBlocked:s.marginBlocked,
  needsRecheck:s.recheck,
  staleApprovals:s.stale,
  activeSales:s.activeSales
}}];

// Webhook calls must carry the shared secret; manual runs skip this check
const cfg=$input.first().json;
let body;
try{ body=$('Refresh Webhook').first().json.body; }catch(e){ body=undefined; }
if(body!==undefined && String((body||{}).secret||'')!==String(cfg.webhookSecret||'')){
  throw new Error('Wrong or missing secret');
}
return [{json:cfg}];
